import{_ as a,a as t,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 2 Breakfast or lunch?","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 2 Breakfast or lunch?","description":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般现在时与习惯，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 1 A private conversation","link":"/life/english/new-concept/book-2/unit-01/lesson-001"},"next":{"text":"第二册：实践与进步 · Lesson 3 Please send me a card","link":"/life/english/new-concept/book-2/unit-01/lesson-003"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 1 A private conversation","link":"/life/english/new-concept/book-2/unit-01/lesson-001"},"next":{"text":"第二册：实践与进步 · Lesson 3 Please send me a card","link":"/life/english/new-concept/book-2/unit-01/lesson-003"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-002.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-002.md"}'),o={name:"life/english/new-concept/book-2/unit-01/lesson-002.md"};function l(r,e,i,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-2-breakfast-or-lunch" tabindex="-1">第二册：实践与进步 · Lesson 2 Breakfast or lunch? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-2-breakfast-or-lunch" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 2 Breakfast or lunch?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>周末作息和工作日不同，闹钟响过之后仍可能很晚才吃第一餐；练习区分习惯与一次事件。本课的语言观察是：usually 描述常态，不说明每一天都如此。主语 Leo 是第三人称单数时用 eats；换成 does 问句后 eat 恢复原形。完成学习后，请比较自己工作日和周末的作息，至少使用两个频率副词。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>breakfast</td><td>/ˈbrekfəst/</td><td>n.</td><td>早餐</td><td>have breakfast</td></tr><tr><td>late</td><td>/leɪt/</td><td>adv.</td><td>晚；迟</td><td>arrive late</td></tr><tr><td>habit</td><td>/ˈhæbɪt/</td><td>n.</td><td>习惯</td><td>a daily habit</td></tr><tr><td>alarm</td><td>/əˈlɑːm/</td><td>n.</td><td>闹钟；警报</td><td>set an alarm</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>get up — 起床，不等于醒来</li><li>on weekdays — 在工作日，复数表示通常的周一至周五</li></ul><h2 id="语法讲解-一般现在时与习惯" tabindex="-1">语法讲解：一般现在时与习惯 <a class="header-anchor" href="#语法讲解-一般现在时与习惯" aria-label="Permalink to &quot;语法讲解：一般现在时与习惯&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：usually 描述常态，不说明每一天都如此。主语 Leo 是第三人称单数时用 eats；换成 does 问句后 eat 恢复原形。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Leo usually eats breakfast before seven.</p></blockquote><p>利奥通常七点前吃早餐。</p><p>Leo 是单数主语，eats 是习惯性动作，usually 位于实义动词前，before seven 给出时间边界。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分别朗读 usually、sometimes；将 Sunday 与 weekday 所在语块重读以表达对照。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Leo usually eats breakfast before seven. On Sundays he turns off his alarm. He sometimes has his first meal at eleven.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较自己工作日和周末的作息，至少使用两个频率副词。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Leo 是单数主语，eats 是习惯性动作，usually 位于实义动词前，before seven 给出时间边界。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 eat/eats：Leo usually ___ breakfast before seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eats</p><p><strong>解析：</strong> 第三人称单数的肯定句使用 eats。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>利奥周日第一餐有时几点吃？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> At eleven.</p><p><strong>解析：</strong> 示范用 sometimes，不能推断每个周日都十一点吃。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 Leo eats breakfast early 改为一般疑问句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Does Leo eat breakfast early?</p><p><strong>解析：</strong> does 后实义动词恢复为 eat。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般现在时与习惯。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-001">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-003">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",l]]);export{p as __pageData,b as default};
